g=[[0]*15 for _ in range(15)]
# horizontal bars preserve their cells and fill their gaps
bars={2:(2,range(0,6)),3:(5,range(6,15)),6:(3,range(0,7)),8:(9,range(6,15)),11:(4,range(0,15))}
for r,(v,cs) in bars.items():
 for c in cs:g[r][c]=v
# vertical tracks from the bottom markers, segmented upward by horizontal bars; marker-origin segment stays its own color
# col3: at bar rows 11,6,2 the bar color extends upward to preceding boundary
for r0,r1,v in [(12,14,6),(7,10,4),(3,5,3),(0,1,2)]:
 for r in range(r0,r1+1):g[r][3]=v
# col8: bottom marker 8; horizontal bars encountered upward override to their own color until next bar
for r0,r1,v in [(12,14,8),(9,10,4),(4,7,9),(0,2,5)]:
 for r in range(r0,r1+1):g[r][8]=v
